def transform(self, row: dict):
    v = row.get("hba1c_befund")
    if v is None:
        return None
    v = v.strip()
    if v == "Ueber 8":
        return ">8"
    if v == "Nicht gemessen":
        return None
    if v == "Norm":
        return "Norm"
    try:
        num = float(v.replace(",", "."))
        if num > 8:
            return ">8"
        elif num > 7:
            return ">7"
        else:
            return "Norm"
    except:
        return None

def transform(self, row):
